use std::{fs,path::Path};use serde_json::{json,Value};use sha2::{Digest,Sha256};
fn main(){let r=Path::new("/tmp/zopro-isolated-grouping");let a:Value=serde_json::from_slice(&fs::read(r.join("audit-current/results.json")).unwrap()).unwrap();let key="zopro_core::msm_affine::grouping::scalar_groups";let old=&a["accepted-native"]["functions"][key];let new=&a["candidate-native"]["functions"][key];for field in ["size_bytes","instruction_count","stack_reference_instructions","sub_rsp_instructions"]{assert_eq!(old[field],new[field],"code shape {field}");}
 let load=|name:&str|fs::read_to_string(r.join(format!("audit-current/{name}.grouping.normalized.txt"))).unwrap();let before=load("accepted-native");let after=load("candidate-native");let strip=|s:&str|s.lines().map(|line|if line.contains("[rip-relative]"){line.split(" # ").next().unwrap()}else{line}).collect::<Vec<_>>().join("\n");let b=strip(&before);let n=strip(&after);assert_eq!(b,n,"non-relocation instruction difference");let comment_differences=before.lines().zip(after.lines()).filter(|(a,b)|a!=b).count();let source=fs::read(r.join("candidate/crates/zopro-core/src/msm_affine/grouping.rs")).unwrap();let original=fs::read(r.join("grouping.original.rs")).unwrap();assert!(source.starts_with(&original));let json=json!({"original_grouping_structure_preserved":true,"original_grouping_source_prefix_unchanged":true,"size_bytes":old["size_bytes"],"instructions":old["instruction_count"],"static_stack_reference_instructions":old["stack_reference_instructions"],"frame_allocation_bytes":424,"relocation_normalized_instruction_sequence_matches":true,"nearest_symbol_comment_differences":comment_differences,"fingerprint_after_ignoring_RIP_nearest_symbol_comments":format!("{:x}",Sha256::digest(b.as_bytes())),"limitations":"Direct branch displacements normalized to relative target or symbol; RIP displacement/nearest-symbol comments ignored. Does not prove equal global referents, timing, dynamic spills or causality; source hashes and independent math/proof tests establish separate evidence.","previous_bitmap_bytes":a["previous-native"]["functions"][key]["size_bytes"],"previous_bitmap_instructions":a["previous-native"]["functions"][key]["instruction_count"]});fs::write(r.join("codegen-review.json"),serde_json::to_vec_pretty(&json).unwrap()).unwrap();println!("Originalgrouping7624B/1584instructions/424Bframe preserved;{comment_differences}RIPnearest-labeldifferencesonly");}
